<template>
  <base-layout>
    <v-toolbar
      v-if="authenticated"
      flat
      color="grey lighten-3"
      height="50"
    >
      <v-toolbar-title class="subheading">Pengaturan Kolom {{idJenis === 'pabean' ? 'Dokumen Pabean': idJenis === 'mutasi' ? 'Mutasi Bulanan': 'WIP'}}</v-toolbar-title>
      <v-spacer></v-spacer>
      <div>
        <v-btn
          color="primary"
          fab
          small
          dark
          @click.stop="onAdd"
        >
          <v-icon>fa-plus</v-icon>
        </v-btn>
        <v-btn
          class="indigo"
          fab
          small
          dark
          v-show="selectedRow.length === 1"
          @click.stop="onEdit"
        >
          <v-icon>fa-pencil</v-icon>
        </v-btn>
        <v-btn
          color="error"
          fab
          small
          dark
          v-show="selectedRow.length > 0"
          @click.stop="state.isDelete = !state.isDelete"
        >
          <v-icon>fa-trash</v-icon>
        </v-btn>
        <v-btn
          color="success"
          fab
          small
          dark
          @click="state.isRefresh = !state.isRefresh"
        >
          <v-icon>fa-refresh</v-icon>
        </v-btn>
        <!-- <v-btn
          class="blue-grey"
          fab
          small
          dark
          @click="state.isDownload = !state.isDownload"
        >
          <v-icon>fa-download</v-icon>
        </v-btn> -->
      </div>
    </v-toolbar>
    <v-layout
      row
      wrap
    >
      <v-flex
        xs12
        class="pa-4"
      >
        <table-view
          from-file="setting"
          :is-refresh="state.isRefresh"
          :is-delete="state.isDelete"
          :on-select="onSelect"
          :get-items="onGetItems"
          :rows-per-page="1000"
          :on-deleted="onDeleted"
          :extra-query-options="tableQueryOptions"
        />
        <div class="mt-3">
          <v-btn
            small
            class="mx-0 mr-2"
            v-show="selectedRow.length === 1 && !isFirstIndex"
            @click="move('first')"
          >
            <v-icon>fa-arrow-up</v-icon>
            <v-icon>fa-arrow-up</v-icon>
          </v-btn>
          <v-btn
            small
            class="mx-0 mr-2"
            v-show="selectedRow.length === 1 && !isFirstIndex"
            @click="move('prev')"
          >
            <v-icon>fa-arrow-up</v-icon>
          </v-btn>
          <v-btn
            small
            class="mx-0 mr-2"
            v-show="selectedRow.length === 1 && !isLastIndex"
            @click="move('next')"
          >
            <v-icon>fa-arrow-down</v-icon>
          </v-btn>
          <v-btn
            small
            class="mx-0 mr-2"
            v-show="selectedRow.length === 1 && !isLastIndex"
            @click="move('last')"
          >
            <v-icon>fa-arrow-down</v-icon>
            <v-icon>fa-arrow-down</v-icon>
          </v-btn>
        </div>
      </v-flex>
      <v-flex
        xs12
        class="px-4 pb-4 table-sm mb-5"
        v-show="tmpDataSetting.length > 0"
      >
        <div class="mb-3">Contoh Tampilan :</div>
        <table-view
          :from-file="idJenis"
          :is-refresh-columns="state.isRefresh"
          :extra-query-options="{LIMIT: 5}"
          :show-pagination="false"
        />
      </v-flex>
    </v-layout>
    <query-service
      v-model="settings"
      from-file="setting"
      :extra-query-options="settingQueryOptions"
      :on-loaded="onLoadedSettings"
    />
  </base-layout>
</template>

<script>
import _filter from "lodash/filter";

import { post } from "@/utils/proxy";
import { modal } from "@/utils/modal";

import FormAddEdit from "./FormAddEdit";

export default {
  data() {
    return {
      state: {
        isAdd: false,
        isEdit: false,
        isRefresh: false,
        isDelete: false,
        isDownload: false
      },
      selectedRow: [],
      settings: [],
      dataSetting: [],
      tmpDataSetting: [],
      allFields: []
    };
  },
  created() {},
  methods: {
    onLoadedSettings(data) {
      let fields = [];
      if (this.idJenis === "pabean") {
        if (data[0]) {
          fields = Object.keys(data[0][0]);
        }
      }
      if (this.idJenis === "mutasi") {
        if (data[1]) {
          fields = Object.keys(data[1][0]);
        }
      }
      if (this.idJenis === "wip") {
        if (data[2]) {
          fields = Object.keys(data[2][0]);
        }
      }
      this.allFields = fields;
    },
    onGetItems(data) {
      this.dataSetting = [].concat(data);
      this.tmpDataSetting = [].concat(data);
    },
    onDeleted(deletedId) {
      const newData = _filter(
        this.tmpDataSetting,
        o => deletedId.indexOf(o.no_kolom) < 0
      );
      this.saveSetting(newData);
    },
    moveArray(data, oldIndex, newIndex) {
      const newData = [].concat(data);
      while (oldIndex < 0) {
        oldIndex += newData.length;
      }
      while (newIndex < 0) {
        newIndex += newData.length;
      }
      if (newIndex >= newData.length) {
        let k = newIndex - newData.length;
        while (k + 1) {
          newData.push(undefined);
          k -= 1;
        }
      }
      newData.splice(newIndex, 0, newData.splice(oldIndex, 1)[0]);
      return newData;
    },
    move(type) {
      let newData = [];
      const currentIndex = parseInt(this.selectedRow[0].no_kolom, 10) - 1;
      const lastIndex = this.tmpDataSetting.length - 1;
      switch (type) {
        case "first":
          newData = this.moveArray(this.tmpDataSetting, currentIndex, 0);
          break;
        case "last":
          newData = this.moveArray(
            this.tmpDataSetting,
            currentIndex,
            lastIndex
          );
          break;
        case "prev":
          newData = this.moveArray(
            this.tmpDataSetting,
            currentIndex,
            currentIndex - 1
          );
          break;
        case "next":
          newData = this.moveArray(
            this.tmpDataSetting,
            currentIndex,
            currentIndex + 1
          );
          break;
        default:
          newData = newData.concat(this.tmpDataSetting);
      }
      this.saveSetting(newData);
    },
    onSelect(row) {
      this.selectedRow = row;
    },
    onAdd() {
      modal({
        name: "full-modal",
        props: {
          type: "add",
          availableFields: this.availableFields,
          dataSetting: this.dataSetting,
          idJenis: this.idJenis
        },
        dismissable: false,
        component: FormAddEdit
      }).then(response => {
        if (response) {
          this.state.isRefresh = !this.state.isRefresh;
        }
      });
    },
    onEdit() {
      modal({
        name: "full-modal",
        props: {
          type: "edit",
          data: this.selectedRow[0],
          availableFields: [this.selectedRow[0].nama_field].concat(
            this.availableFields
          ),
          dataSetting: this.dataSetting,
          idJenis: this.idJenis
        },
        dismissable: false,
        component: FormAddEdit
      }).then(response => {
        if (response) {
          this.state.isRefresh = !this.state.isRefresh;
        }
      });
    },
    saveSetting(newData) {
      const data = newData.map((item, index) =>
        Object.assign(item, { no_kolom: index + 1 })
      );
      post("page/beacukai/saveSetting", { data, id: this.idJenis }).then(
        response => {
          if (response.success_message) {
            this.state.isRefresh = !this.state.isRefresh;
          }
        }
      );
    }
  },
  computed: {
    idJenis() {
      let id = "pabean";
      switch (this.$route.path) {
        case "/pengaturan-kolom-pabean":
          id = "pabean";
          break;
        case "/pengaturan-kolom-mutasi":
          id = "mutasi";
          break;
        case "/pengaturan-kolom-wip":
          id = "wip";
          break;
        default:
          id = "pabean";
      }
      return id;
    },
    authenticated() {
      return this.$store.state.auth.authenticated;
    },
    user() {
      return this.$store.state.auth.user;
    },
    windowSize() {
      return this.$store.state.app.windowSize;
    },
    tableQueryOptions() {
      return {
        jenis: this.idJenis
      };
    },
    settingQueryOptions() {
      return [{ LIMIT: 1 }, { LIMIT: 1 }, { LIMIT: 1 }];
    },
    availableFields() {
      const fields = [];
      const settingFields = this.dataSetting.map(item => item.nama_field);
      this.allFields.forEach(item => {
        if (settingFields.indexOf(item) < 0) {
          if (item !== "id") fields.push(item);
        }
      });
      return fields;
    },
    isFirstIndex() {
      let isFirstIndex = false;
      if (this.selectedRow.length === 1) {
        isFirstIndex = parseInt(this.selectedRow[0].no_kolom, 10) === 1;
      }
      return isFirstIndex;
    },
    isLastIndex() {
      let isLastIndex = false;
      if (this.selectedRow.length === 1) {
        isLastIndex =
          parseInt(this.selectedRow[0].no_kolom, 10) ===
          this.dataSetting.length;
      }
      return isLastIndex;
    }
  },
  watch: {
    $route() {
      this.state.isRefresh = !this.state.isRefresh;
    }
  }
};
</script>




