<template>
  <div>
    <v-toolbar
      class="indigo"
      dark
      height="50"
    >
      <v-toolbar-title>{{type=='edit' ? 'Update': 'Add'}} Kolom</v-toolbar-title>
      <v-spacer></v-spacer>
      <v-btn
        icon
        @click.native="cancel()"
        dark
      >
        <v-icon>close</v-icon>
      </v-btn>
    </v-toolbar>
    <v-flex>
      <v-form ref="form">
        <v-card
          flat
          class="pa-4"
        >
          <v-layout
            row
            wrap
          >
            <v-flex
              xs12
              md4
              class="px-2"
            >
              <v-select
                :items="availableFields"
                v-model="input.namaField"
                label="Nama Field"
                name="Nama Field"
                :error-messages="errors.collect('Nama Field')"
                v-validate="'required'"
              ></v-select>
            </v-flex>
            <v-flex
              xs12
              md4
              class="px-2"
            >
              <v-text-field
                label="Lebar"
                name="Lebar"
                v-model="input.lebar"
                :error-messages="errors.collect('Lebar')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md4
              class="px-2"
            >
              <v-text-field
                label="Lebar Print"
                name="Lebar Print"
                v-model="input.lebarPrint"
                :error-messages="errors.collect('Lebar Print')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md4
              class="px-2"
            >
              <v-select
                :items="['left', 'center', 'right']"
                label="Alignment"
                name="Alignment"
                v-model="input.alignment"
                :error-messages="errors.collect('Alignment')"
                v-validate="'required'"
              ></v-select>
            </v-flex>
            <v-flex
              xs12
              md4
              class="px-2"
            >
              <v-text-field
                label="Keterangan"
                name="Keterangan"
                v-model="input.keterangan"
                :error-messages="errors.collect('Keterangan')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
          </v-layout>
        </v-card>
        <v-divider></v-divider>
        <v-card
          flat
          class="pa-3"
        >
          <v-btn
            color="success"
            @click="submit()"
          >Simpan</v-btn>
          <v-btn
            color="error"
            @click="cancel()"
          >Batal</v-btn>
        </v-card>
      </v-form>
    </v-flex>
  </div>
</template>

<script>
import { post } from "@/utils/proxy";

export default {
  props: {
    type: {
      type: String
    },
    data: {
      type: Object
    },
    availableFields: {},
    dataSetting: {},
    selectedIndex: {},
    idJenis: {}
  },
  data: () => ({
    input: {
      namaField: "",
      lebar: "",
      lebarPrint: "",
      alignment: "",
      keterangan: ""
    }
  }),
  created() {
    if (this.type === "edit") {
      this.input = {
        namaField: this.data.nama_field,
        lebar: this.data.lebar,
        lebarPrint: this.data.lebar_print,
        alignment: this.data.alignment,
        keterangan: this.data.keterangan
      };
    }
  },
  methods: {
    submit() {
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          post("page/beacukai/saveSetting", this.inputParams).then(response => {
            if (response.success_message) {
              this.$vuedals.close(true);
            }
          });
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    },
    cancel() {
      this.$vuedals.close(false);
    }
  },
  computed: {
    inputData() {
      const data = {
        nama_field: this.input.namaField,
        lebar: this.input.lebar,
        lebar_print: this.input.lebarPrint,
        alignment: this.input.alignment,
        keterangan: this.input.keterangan,
        jenis: this.idJenis
      };
      return data;
    },
    inputParams() {
      const data = this.dataSetting;
      if (this.type === "add") {
        data.push(
          Object.assign(this.inputData, {
            no_kolom: this.dataSetting.length + 1
          })
        );
      }
      if (this.type === "edit") {
        data[this.data.no_kolom - 1] = Object.assign(this.inputData, {
          no_kolom: this.data.no_kolom
        });
      }
      const params = {
        data,
        id: this.idJenis
      };
      return params;
    }
  }
};
</script>

<style lang="css">
</style>



